    80→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
    81→  const { t } = useTranslation();
    82→  const { isStreaming, editMessage, deleteMessage } = useAgent();
    83→  const [isEditing, setIsEditing] = useState(false);
    84→  const [editText, setEditText] = useState(message.content);
    85→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
    86→  const textareaRef = useRef<HTMLTextAreaElement>(null);
    87→
    88→  const isUser = message.role === 'user';
    89→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
    90→
    91→  useEffect(() => {
    92→    if (isEditing && textareaRef.current) {
    93→      textareaRef.current.focus();
    94→      textareaRef.current.selectionStart = textareaRef.current.value.length;
    95→    }
    96→  }, [isEditing]);
    97→
    98→  const handleEdit = () => {
    99→    setEditText(message.content);
   100→    setIsEditing(true);
   101→    setIsConfirmingDelete(false);
   102→  };
   103→
   104→  const handleCancelEdit = () => {
   105→    setIsEditing(false);
   106→    setEditText(message.content);
   107→  };
   108→
   109→  const handleSaveEdit = () => {
   110→    const trimmed = editText.trim();
   111→    if (!trimmed || trimmed === message.content) {
   112→      handleCancelEdit();
   113→      return;
   114→    }
   115→    setIsEditing(false);
   116→    editMessage(messageIndex, trimmed);
   117→  };
   118→
   119→  const handleDeleteConfirm = () => {
   120→    setIsConfirmingDelete(false);
   121→    deleteMessage(messageIndex);
   122→  };
   123→
   124→  const handleKeyDown = (e: React.KeyboardEvent) => {
   125→    if (e.key === 'Escape') {
   126→      handleCancelEdit();
   127→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
   128→      e.preventDefault();
   129→      handleSaveEdit();
   130→    }
   131→  };
   132→
   133→  let streamingRemainder: string | undefined;
   134→  if (hasSegments && message.isStreaming && message.content) {
   135→    const segmentedText = message.segments!
   136→      .filter((s) => s.type !== 'tool')
   137→      .map((s) => s.text || '')
   138→      .join('');
   139→    const remaining = message.content.slice(segmentedText.length);
   140→    if (remaining.trim()) {
   141→      streamingRemainder = remaining;
   142→    }
   143→  }
   144→
   145→  const hasAnswer = hasSegments && message.segments!.some((s) => s.type === 'answer');
   146→  const isInAnswerPhase = message.currentPhase === 'answer';
   147→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
   148→
   149→  const answerSegments = hasSegments
   150→    ? message.segments!.filter((s) => s.type === 'answer' && s.text?.trim())
   151→    : [];
   152→
   153→  return (
   154→    <div className={`message-bubble message-bubble--${message.role}`}>
   155→      <div className="message-bubble__header">
   156→        {isUser ? t('you') : t('assistant')}
   157→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
   158→          <span className="message-bubble__actions">
   159→            <button
   160→              className="message-bubble__action-btn"
   161→              onClick={handleEdit}
   162→              title={t('editMessage')}
   163→            >
   164→              &#9998;
   165→            </button>
   166→            <button
   167→              className="message-bubble__action-btn message-bubble__action-btn--delete"
   168→              onClick={() => setIsConfirmingDelete(true)}
   169→              title={t('deleteMessage')}
   170→            >
   171→              &#128465;
   172→            </button>
   173→          </span>
   174→        )}
   175→      </div>
   176→
   177→      {isUser && isConfirmingDelete && (
   178→        <div className="message-bubble__confirm-delete">
   179→          <span>{t('deleteConfirm')}</span>
   180→          <div className="message-bubble__confirm-actions">
   181→            <button
   182→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
   183→              onClick={handleDeleteConfirm}
   184→            >
   185→              {t('delete')}
   186→            </button>
   187→            <button
   188→              className="message-bubble__confirm-btn"
   189→              onClick={() => setIsConfirmingDelete(false)}
   190→            >
   191→              {t('cancel')}
   192→            </button>
   193→          </div>
   194→        </div>
   195→      )}
   196→
   197→      {isUser && isEditing ? (
   198→        <div className="message-bubble__edit-mode">
   199→          <textarea
   200→            ref={textareaRef}
   201→            className="message-bubble__edit-textarea"
   202→            value={editText}
   203→            onChange={(e) => setEditText(e.target.value)}
   204→            onKeyDown={handleKeyDown}
   205→            rows={3}
   206→          />
   207→          <div className="message-bubble__edit-actions">
   208→            <button
   209→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
   210→              onClick={handleSaveEdit}
   211→            >
   212→              {t('saveResend')}
   213→            </button>
   214→            <button
   215→              className="message-bubble__edit-btn"
   216→              onClick={handleCancelEdit}
   217→            >
   218→              {t('cancel')}
   219→            </button>
   220→          </div>
   221→        </div>
   222→      ) : hasSegments ? (
   223→        <div className="message-bubble__segments">
   224→          <ThinkingBlock
   225→            segments={message.segments!}
   226→            streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
   227→            isThinkingPhase={isThinkingPhase}
   228→            isAgentStreaming={!!message.isStreaming}
   229→          />
   230→          {answerSegments.map((seg, i) => (
   231→            <div key={i} className="message-bubble__segment message-bubble__segment--answer">
